const setRunLimit = `-- name: SetRunLimit :execrows

UPDATE runs SET limit_kind = ?1, limit_resets_at = ?2, limit_since = ?3,
  version = version + 1, updated_at = ?4
WHERE id = ?5 AND generation = ?6
  AND (limit_kind != ?1 OR limit_resets_at IS NOT ?2 OR limit_since IS NOT ?3)
`

type SetRunLimitParams struct {
	LimitKind     string
	LimitResetsAt sql.NullInt64
	LimitSince    sql.NullInt64
	Now           int64
	ID            string
	Generation    int64
}

// Usage limits (ADR-0079): a run's reported limit, account holds and parked runs' waits. Times are Unix microseconds.
// A run's limit as its node reported it: limit_kind ” clears it (both times NULL).
func (q *Queries) SetRunLimit(ctx context.Context, arg SetRunLimitParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setRunLimit,
		arg.LimitKind,
		arg.LimitResetsAt,
		arg.LimitSince,
		arg.Now,
		arg.ID,
		arg.Generation,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

